// Ported from the Node app's Sequelize model StudentAccount (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class StudentAccountConfiguration : IEntityTypeConfiguration<StudentAccount>
{
    public void Configure(EntityTypeBuilder<StudentAccount> builder)
    {
        builder.ToTable("student_accounts");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.UserId).HasColumnName("user_id");
        builder.Property(e => e.StudentId).HasColumnName("student_id");
        builder.HasIndex(e => e.UserId).IsUnique();
        builder.HasIndex(e => e.StudentId).IsUnique();
        builder.HasOne(e => e.User).WithOne(p => p.StudentAccount).HasForeignKey<StudentAccount>(e => e.UserId).OnDelete(DeleteBehavior.NoAction);
        builder.HasOne(e => e.Student).WithOne(p => p.StudentAccount).HasForeignKey<StudentAccount>(e => e.StudentId).OnDelete(DeleteBehavior.NoAction);
    }
}
